#include <bits/stdc++.h>
using namespace std;

bool isMatch(const string& pattern, int num) {
    int lastDigit = -1;
    int len = pattern.length();
    for (int i = len - 1; i >= 0; i--) {
        int currentDigit = num % 10;
        char c = pattern[i];
        if (c == 'X') {
            if (lastDigit >= 0 && lastDigit != currentDigit) {
                return false;
            }
            lastDigit = currentDigit;
        } else if (c != '_') {
            if ((c - '0') != currentDigit) {
                return false;
            }
        }
        if (len > 1 && i == 0 && currentDigit == 0) {
            return false;
        }
        num /= 10;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string patternStr;
    cin >> patternStr;
    int maxNumber = 1;
    for (size_t i = 0; i < patternStr.length(); i++) {
        maxNumber *= 10;
    }
    int total = 0;
    for (int num = 0; num < maxNumber; num += 25) {
        if (isMatch(patternStr, num)) {
            total++;
        }
    }
    cout << total << "\n";
    return 0;
}

